package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Loading is strict: a missing file, a missing required key, an unparsable or out-of-range value, or an
 * unrecognised key all fail with a {@link ConfigException} that lists every problem found. A key that is absent
 * gets its default; a key that is present but wrong never does.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);
    static final boolean DEFAULT_METRICS_ENABLED = false;

    static final String UPSTREAM_URL = "upstream.url";
    static final String API_TOKEN = "api.token";
    static final String WORKER_THREADS = "worker.threads";
    static final String QUEUE_CAPACITY = "queue.capacity";
    static final String RETRY_MAX_ATTEMPTS = "retry.max-attempts";
    static final String REQUEST_TIMEOUT = "request.timeout";
    static final String METRICS_ENABLED = "metrics.enabled";

    private static final Set<String> KNOWN_KEYS = Set.of(
            UPSTREAM_URL, API_TOKEN, WORKER_THREADS, QUEUE_CAPACITY, RETRY_MAX_ATTEMPTS, REQUEST_TIMEOUT,
            METRICS_ENABLED);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        return new Validator(read(file)).validate();
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("cannot read configuration file " + file.toAbsolutePath() + ": " + e);
        }
        return properties;
    }

    /** Checks one set of properties, collecting every problem instead of stopping at the first. */
    private static final class Validator {
        private final Properties properties;
        private final List<String> problems = new ArrayList<>();

        Validator(Properties properties) {
            this.properties = properties;
        }

        ServiceConfig validate() {
            rejectUnknownKeys();
            ServiceConfig config = new ServiceConfig(
                    upstreamUrl(),
                    requiredText(API_TOKEN),
                    intAtLeast(WORKER_THREADS, DEFAULT_WORKER_THREADS, 1),
                    intAtLeast(QUEUE_CAPACITY, DEFAULT_QUEUE_CAPACITY, 1),
                    intAtLeast(RETRY_MAX_ATTEMPTS, DEFAULT_RETRY_ATTEMPTS, 0),
                    duration(REQUEST_TIMEOUT, DEFAULT_REQUEST_TIMEOUT),
                    bool(METRICS_ENABLED, DEFAULT_METRICS_ENABLED));
            if (!problems.isEmpty()) {
                throw new ConfigException(problems);
            }
            return config;
        }

        private void rejectUnknownKeys() {
            Set<String> unknown = new TreeSet<>(properties.stringPropertyNames());
            unknown.removeAll(KNOWN_KEYS);
            for (String key : unknown) {
                problems.add(key + " is not a recognised key (misspelled?); known keys are "
                        + new TreeSet<>(KNOWN_KEYS));
            }
        }

        private URI upstreamUrl() {
            String raw = requiredText(UPSTREAM_URL);
            if (raw == null) {
                return null;
            }
            try {
                URI uri = new URI(raw);
                if (isHttpUrlWithHost(uri)) {
                    return uri;
                }
            } catch (URISyntaxException e) {
                // reported below
            }
            problems.add(UPSTREAM_URL + " must be an http or https URL with a host, got '" + raw + "'");
            return null;
        }

        private static boolean isHttpUrlWithHost(URI uri) {
            String scheme = uri.getScheme();
            return ("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme)) && uri.getHost() != null;
        }

        private String requiredText(String key) {
            String raw = properties.getProperty(key);
            if (raw == null || raw.isBlank()) {
                problems.add(key + " is required");
                return null;
            }
            return raw.trim();
        }

        private int intAtLeast(String key, int defaultValue, int minimum) {
            String raw = properties.getProperty(key);
            if (raw == null) {
                return defaultValue;
            }
            try {
                int value = Integer.parseInt(raw.trim());
                if (value >= minimum) {
                    return value;
                }
            } catch (NumberFormatException e) {
                // reported below
            }
            problems.add(key + " must be a whole number of at least " + minimum + ", got '" + raw + "'");
            return defaultValue;
        }

        private Duration duration(String key, Duration defaultValue) {
            String raw = properties.getProperty(key);
            if (raw == null) {
                return defaultValue;
            }
            Matcher matcher = DURATION.matcher(raw.trim());
            if (matcher.matches()) {
                try {
                    return toDuration(Long.parseLong(matcher.group(1)), matcher.group(2));
                } catch (ArithmeticException | NumberFormatException e) {
                    // reported below
                }
            }
            problems.add(key + " must be a whole number followed by ms, s or m (for example 30s), got '"
                    + raw + "'");
            return defaultValue;
        }

        private static Duration toDuration(long amount, String unit) {
            return switch (unit) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        }

        private boolean bool(String key, boolean defaultValue) {
            String raw = properties.getProperty(key);
            if (raw == null) {
                return defaultValue;
            }
            String value = raw.trim();
            if (value.equalsIgnoreCase("true")) {
                return true;
            }
            if (value.equalsIgnoreCase("false")) {
                return false;
            }
            problems.add(key + " must be true or false, got '" + raw + "'");
            return defaultValue;
        }
    }
}

