void reportsEveryProblemAtOnce() throws IOException {
    Path file = write("api.token=\nworker.threads=four\nrequest.timeout=30\n");

    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

    assertEquals(4, error.problems().size(), error.getMessage());
    for (String key : new String[] {"upstream.url", "api.token", "worker.threads", "request.timeout"}) {
        assertTrue(error.getMessage().contains(key), error.getMessage());
    }
}

@Test
void neverEchoesTheApiToken() throws IOException {
    Path file = write(REQUIRED + "worker.threads=four\n");

    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

    assertFalse(error.getMessage().contains("s3cret"));
}

private void assertSingleProblem(String content, String... expectedFragments) throws IOException {
    Path file = write(content);

    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

    assertEquals(1, error.problems().size(), error.getMessage());
    for (String fragment : expectedFragments) {
        assertTrue(error.getMessage().contains(fragment), error.getMessage());
    }
}

